function parts(ms){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(ms);const v={};for(const x of p)v[x.type]=+x.value;return {y:v.year,m:v.month,d:v.day,h:v.hour,min:v.minute,sec:v.second}}
function weekday(y,m,d){return new Date(Date.UTC(y,m-1,d)).getUTCDay()}
function weekdays(y,m){let n=0,days=new Date(Date.UTC(y,m,0)).getUTCDate();for(let d=1;d<=days;d++){let w=weekday(y,m,d);if(w!==0&&w!==6)n++}return n}
function salaryTotals(now){const t=parts(now),today=Date.UTC(t.y,t.m-1,t.d),dayOfWeek=weekday(t.y,t.m,t.d),monday=today-((dayOfWeek+6)%7)*86400000,monthStart=Date.UTC(t.y,t.m-1,1);let week=0,month=0;for(let d=Math.min(monday,monthStart);d<=today;d+=86400000){const dt=new Date(d),y=dt.getUTCFullYear(),m=dt.getUTCMonth()+1,day=dt.getUTCDate(),w=weekday(y,m,day);if(w===0||w===6)continue;const daily=40000/weekdays(y,m),earned=d===today?daily*Math.max(0,Math.min(32400,(t.h-8)*3600+t.min*60+t.sec))/32400:daily;if(d>=monday)week+=earned;if(d>=monthStart)month+=earned;}return {week,month};}
function workMinutes(a,b){let total=0,cur=Math.floor((a+28800000)/86400000)*86400000-28800000;for(let i=0;cur<b&&i<380;i++,cur+=86400000){const d=new Date(cur+28800000),w=d.getUTCDay();if(w===0||w===6)continue;const begin=cur+8*3600000,end=cur+17*3600000;total+=Math.max(0,Math.min(b,end)-Math.max(a,begin))/60000}return total}
const EQUIPMENT_SETS=[{id:'bonus',name:'年終獎金幻術師',icon:'💸',names:['年終獎金真的存在之戒','薪水入帳五秒後消失的神話護符','主管看不到我的隱形西裝'],two:'暴擊 +7%',three:'攻擊 +12%，生命 +12%'},{id:'monday',name:'週一生存專家',icon:'☕',names:['週一免疫防撞帽','加班費不存在的虛空鎧甲','主管靠近就會自動起飛的拖鞋'],two:'生命 +14%',three:'防禦 +18%，閃避 +4%'},{id:'meeting',name:'會議終結者',icon:'📵',names:['永久免開會的聖職識別證','自動回覆「收到」的神聖頭盔','已核准的離職申請聖劍'],two:'攻擊 +9%',three:'暴擊 +8%，防禦 +10%'},{id:'coffee',name:'咖啡因永動機',icon:'☕',names:['永遠寫不完的週報法杖','傳說中的準時下班之戒','下午五點零一分的傳送鞋'],two:'閃避 +6%',three:'攻擊 +10%，生命 +15%'},{id:'clockout',name:'準時下班聯盟',icon:'🌇',names:['已核准的離職申請聖劍','下午五點零一分的傳送鞋','傳說中的準時下班之戒','永久免開會的聖職識別證'],two:'閃避 +8%',three:'攻擊 +15%，暴擊 +5%'},{id:'stealth',name:'辦公室隱身術',icon:'🥷',names:['自動回覆「收到」的神聖頭盔','主管看不到我的隱形西裝','主管靠近就會自動起飛的拖鞋','週一免疫防撞帽'],two:'防禦 +12%',three:'生命 +18%，閃避 +5%'},{id:'overtime',name:'無限加班魔導團',icon:'📑',names:['永遠寫不完的週報法杖','主管的最後一根頭髮戰錘','加班費不存在的虛空鎧甲','薪水入帳五秒後消失的神話護符'],two:'攻擊 +10%',three:'暴擊 +10%，生命 +10%'}];
function setForItem(it){return it&&EQUIPMENT_SETS.find(set=>set.names.includes(it.name))}
function setProgress(equipped=s.equipped){return EQUIPMENT_SETS.map(set=>({...set,count:Object.values(equipped).filter(it=>it&&set.names.includes(it.name)).length}))}
function setCodexHTML(){const owned=new Set([...(s.collection||[]),...s.inventory.map(it=>it.name),...Object.values(s.equipped).filter(Boolean).map(it=>it.name)]);const names=[...new Set(EQUIPMENT_SETS.flatMap(set=>set.names))];const count=names.filter(name=>owned.has(name)).length;return '<div class="codex-progress"><strong>傳說神器已發現 '+count+' / '+names.length+'</strong><div class="codex-progress-bar"><i style="width:'+(count/names.length*100)+'%"></i></div><small>曾經獲得即永久解鎖圖鑑；不需要持續穿戴。</small></div><div class="codex-grid">'+EQUIPMENT_SETS.map(set=>'<div class="codex-group"><h4>'+set.icon+' '+escapeHtml(set.name)+'</h4><div class="codex-items">'+set.names.map(name=>{const unlocked=owned.has(name),slot=Object.keys(OFFICE_ARTIFACTS).find(slot=>OFFICE_ARTIFACTS[slot].some(a=>a[0]===name))||'武器',lore=(OFFICE_ARTIFACTS[slot]||[]).find(a=>a[0]===name);return '<article class="codex-item '+(unlocked?'codex-unlocked':'codex-locked')+'" aria-label="'+(unlocked?escapeHtml(name):'尚未發現的'+slot)+'"><div class="codex-portrait">'+gearArt(slot)+'<span class="codex-mystery" aria-hidden="true">?</span></div><div class="codex-item-text"><strong>'+(unlocked?escapeHtml(name):'？？？ · '+slot)+'</strong><small>'+(unlocked?escapeHtml(lore?lore[1]:'已發現的傳說裝備'):'尚未解鎖 · 神秘裝備剪影')+'</small></div></article>'}).join('')+'</div></div>').join('')+'</div>'}
function setBonusHTML(){return '<div class="set-bonus-list">'+setProgress().map(set=>'<article class="set-bonus '+(set.count>=2?'set-active':'')+'"><strong>'+set.icon+' '+set.name+'　'+set.count+'/4</strong><p class="'+(set.count>=2?'set-unlocked':'')+'">2 件：'+set.two+'</p><p class="'+(set.count>=3?'set-unlocked':'')+'">3 件：'+set.three+'</p><small>收集：'+set.names.map(n=>Object.values(s.equipped).some(it=>it&&it.name===n)?'✓ '+escapeHtml(n):'◇ '+escapeHtml(n)).join(' · ')+'</small></article>').join('')+'</div>'}
function stats(equipped=s.equipped){let atk=10+s.level*3+(s.weapon-1)*4,def=4+s.level*2,hp=90+s.level*12,crit=.06,dodge=.03;for(const it of Object.values(equipped)){if(!it)continue;atk+=it.atk;def+=it.def;hp+=it.hp;if(it.affix==='暴擊')crit+=it.bonus/100;if(it.affix==='閃避')dodge+=it.bonus/100}atk+=Math.floor(s.home/2);for(const set of setProgress(equipped)){if(set.count>=2){if(set.id==='clockout')dodge+=.08;if(set.id==='stealth')def=Math.round(def*1.12);if(set.id==='overtime')atk=Math.round(atk*1.10);if(set.id==='bonus')crit+=.07;if(set.id==='monday')hp=Math.round(hp*1.14);if(set.id==='meeting')atk=Math.round(atk*1.09);if(set.id==='coffee')dodge+=.06}if(set.count>=3){if(set.id==='clockout'){atk=Math.round(atk*1.15);crit+=.05}if(set.id==='stealth'){hp=Math.round(hp*1.18);dodge+=.05}if(set.id==='overtime'){crit+=.10;hp=Math.round(hp*1.10)}if(set.id==='bonus'){atk=Math.round(atk*1.12);hp=Math.round(hp*1.12)}if(set.id==='monday'){def=Math.round(def*1.18);dodge+=.04}if(set.id==='meeting'){crit+=.08;def=Math.round(def*1.10)}if(set.id==='coffee'){atk=Math.round(atk*1.10);hp=Math.round(hp*1.15)}}}return {atk,def,hp,crit,dodge,power:Math.floor(atk*2+def*1.5+hp*.28+crit*100+dodge*75)}}
function rarity(){let r=Math.random()*100;for(let i=0;i<6;i++){r-=[54,27,12,5,1.7,.3][i];if(r<0)return i}return 0}
function makeItem(level,force){const slot=pick(SLOTS),r=force===undefined?rarity():force,scale=(5+level*2)*MULT[r],affix=pick(AFFIX),bonus=2+r*2+rand(4),name=(r>=4&&Math.random()<.55?pick(OFFICE_ARTIFACTS[slot])[0]:(r>=4?'':pick(PREFIX)+' ')+pick(BASE[slot])+(r>=4?' · '+pick(SUFFIX):''));return {id:++s.serial,slot,r,name,level,atk:Math.round(scale*(slot==='武器'?1.2:.15)),def:Math.round(scale*(['頭盔','盔甲','鞋子'].includes(slot)?.7:.12)),hp:Math.round(scale*(slot==='盔甲'?3:1.3)),affix,bonus,upgrade:0}}
let lootRevealQueue=[],lootRevealBusy=false;
function queueLootReveal(it,first){if(!it||it.r<4)return;lootRevealQueue.push({name:it.name,slot:it.slot,r:it.r,first:!!first,set:setForItem(it)});if(lootRevealQueue.length>12)lootRevealQueue=lootRevealQueue.slice(-12);showNextLootReveal()}
function showNextLootReveal(){if(lootRevealBusy||!lootRevealQueue.length||document.hidden)return;const item=lootRevealQueue.shift();lootRevealBusy=true;const reduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;const overlay=document.createElement('div');overlay.className='loot-reveal-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','傳說裝備獲得');overlay.innerHTML='<div class="loot-reveal-panel rarity-'+item.r+'"><div class="loot-reveal-beam"></div><div class="loot-reveal-label">'+(item.first?'✦ 圖鑑首次解鎖 ✦':'✦ 傳說戰利品 ✦')+'</div><div class="loot-reveal-icon">'+gearArt(item.slot)+'</div><div class="loot-reveal-title">'+escapeHtml(item.name)+'</div><div class="loot-reveal-sub">'+(item.set?item.set.icon+' '+escapeHtml(item.set.name):'傳說神器')+' · '+escapeHtml(RAR[item.r])+'</div><button class="btn primary loot-reveal-dismiss" type="button">收入背包 ✦</button></div>';document.body.appendChild(overlay);const btn=overlay.querySelector('button');const close=()=>{overlay.remove();lootRevealBusy=false;showNextLootReveal()};btn.addEventListener('click',close,{once:true});overlay.addEventListener('click',e=>{if(e.target===overlay)close()});if(!reduced)overlay.querySelector('.loot-reveal-panel').classList.add('loot-reveal-animated');btn.focus()}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)showNextLootReveal()});
function loot(level,force){const it=makeItem(level,force);if(s.inventory.length>=MAX){s.materials+=2+it.r*3;log('背包已滿，裝備自動分解。')}else{const first=!s.collection.includes(it.name);s.inventory.push(it);if(first)s.collection.push(it.name);log('掉落 '+RAR[it.r]+'：「'+it.name+'」');queueLootReveal(it,first)}return it}
function xp(n){s.xp+=n;while(s.xp>=s.level*35+45){s.xp-=s.level*35+45;s.level++;log('升到 Lv.'+s.level+'！')}}
function wildBattle(silent=false){const result=wildEncounter(),enemy=result.enemyName;if(result.win){s.kills++;s.coins+=6+Math.floor(s.level/2);xp(6+Math.floor(s.level/4));if(Math.random()<.3)loot(Math.max(1,s.level+rand(4)));else if(Math.random()<.2)s.materials+=1+rand(3);if(!silent){log('擊退「'+enemy+'」，獲得經驗與金幣。');queueEncounter(enemy,true,result)}}else if(!silent){log('「'+enemy+'」擋住了勇者，整頓裝備中。');queueEncounter(enemy,false,result)}return result.win}

let idleReport=null;
function offlineBattle(n){const before={coins:s.coins,xp:s.xp,level:s.level,materials:s.materials,kills:s.kills,serial:s.serial},simulated=Math.min(n,480);let wins=0,jackpots=0,highest=-1;for(let i=0;i<simulated;i++){if(!wildBattle(true))continue;wins++;if(Math.random()<.012){const rarityBoost=Math.random()<.08?5:Math.random()<.25?4:3;const item=loot(Math.max(1,s.level+rand(4)),rarityBoost);highest=Math.max(highest,item.r);jackpots++;}}if(n>simulated){const extra=n-simulated,estimated=Math.floor(extra*Math.max(.35,Math.min(.95,wins/Math.max(1,simulated))));wins+=estimated;s.kills+=estimated;s.coins+=estimated*(6+Math.floor(s.level/2));xp(estimated*(6+Math.floor(s.level/4)));s.materials+=Math.floor(estimated/6);for(let i=0;i<Math.min(40,Math.floor(estimated*.25));i++)loot(Math.max(1,s.level+rand(4)))}const gained={coins:Math.floor(s.coins-before.coins),materials:s.materials-before.materials,kills:s.kills-before.kills,items:s.serial-before.serial,levels:s.level-before.level};idleReport={...gained,wins,battles:n,jackpots,highest,minutes:Math.round(n*3)};log('掛機結算：勝利 '+wins+' / '+n+' 場，掉落 '+gained.items+' 件裝備'+(jackpots?'，幸運暴擊 '+jackpots+' 次':'')+'。');stageToast('掛機勝利 '+wins+' 場 · 裝備 '+gained.items+' 件')}
function showIdleReport(){if(!idleReport)return;let el=document.getElementById('idleRewardOverlay');if(!el){el=document.createElement('div');el.id='idleRewardOverlay';document.body.appendChild(el)}const r=idleReport;el.className='idle-reward-overlay';el.innerHTML='<div class="idle-reward-panel" role="dialog" aria-modal="true" aria-label="掛機戰利品"><div class="idle-reward-star">✦</div><h2>勇者歸來！</h2><p>離線期間，你的勇者沒有偷懶。</p><div class="idle-reward-grid"><div><strong>'+num(r.wins)+'</strong><small>討伐勝利 / '+num(r.battles)+'</small></div><div><strong>+'+num(r.coins)+'</strong><small>冒險金幣</small></div><div><strong>+'+num(r.items)+'</strong><small>裝備掉落</small></div><div><strong>+'+num(r.materials)+'</strong><small>鍛造零件</small></div></div>'+(r.levels?'<p class="idle-reward-level">⬆ 升級 '+r.levels+' 級！</p>':'')+(r.jackpots?'<p class="idle-reward-luck">✨ 幸運掉落 '+r.jackpots+' 次！最高 '+RAR[r.highest]+'</p>':'<p class="idle-reward-tip">下一次也許就能遇到傳說裝備！</p>')+'<button class="btn primary full" data-idle-collect>收下戰利品</button></div>';idleReport=null}
function settle(){const now=Date.now();if(!s.seeded){s.seeded=true;s.last=now;log('勇者正式報到！從現在開始計算掛機收益。')}else if(now>s.last){const previous=Number.isFinite(s.last)?Math.min(s.last,now):now;const delta=workMinutes(Math.max(previous,now-86400000),now);if(delta>0){const before=s.minutes;s.minutes+=delta;s.coins+=delta*(1+(s.weapon-1)/6);const battles=Math.max(0,Math.floor(s.minutes/3)-Math.floor(before/3));if(battles>3)offlineBattle(battles);else for(let i=0;i<battles;i++)wildBattle()}s.last=now}else if(now<s.last-60000){log('偵測到系統時間回退，暫停結算以避免重複領取。')}save()}
function powerOf(it){if(!it)return 0;return it.atk*2+it.def*1.5+it.hp*.28+(it.affix==='暴擊'?it.bonus:it.affix==='閃避'?it.bonus*.75:0)}
function bestEquipmentPlan(){
 // Bounded beam search evaluates full character power, including overlapping set bonuses.
 const pool={};for(const slot of SLOTS){const all=[s.equipped[slot],...s.inventory.filter(it=>it&&it.slot===slot)].filter(Boolean);const ranked=[...all].sort((a,b)=>powerOf(b)-powerOf(a));const selected=ranked.slice(0,4);if(s.equipped[slot]&&!selected.some(x=>x.id===s.equipped[slot].id))selected.push(s.equipped[slot]);for(const it of all)if(setForItem(it)&&!selected.some(x=>x.id===it.id))selected.push(it);pool[slot]=s.equipped[slot]?selected.slice(0,14):[null,...selected.slice(0,14)]}
 let beam=[{eq:{},score:0}];for(const slot of SLOTS){const next=[];for(const state of beam)for(const it of pool[slot]){const eq={...state.eq,[slot]:it},score=stats(eq).power;next.push({eq,score})}next.sort((a,b)=>b.score-a.score);beam=next.slice(0,90)}
 const current=stats().power,best=beam[0];if(!best||best.score<=current+.00001)return [];
 return SLOTS.map(slot=>({slot,it:best.eq[slot],old:s.equipped[slot]})).filter(x=>x.it&&(!x.old||x.it.id!==x.old.id))
}
function equipBest(){const plan=bestEquipmentPlan();if(!plan.length){message('目前已穿戴最佳戰力裝備。');render();return}let count=0;for(const x of plan){const i=s.inventory.findIndex(it=>it.id===x.it.id);if(i<0)continue;s.inventory.splice(i,1);if(x.old)s.inventory.push(x.old);s.equipped[x.slot]=x.it;count++}if(!count)return;message('一鍵裝備完成，換上 '+count+' 件更強裝備！');save();render();equipmentFeedback('✦ 最佳裝備 ×'+count,Math.max(...plan.map(x=>x.it.r||0)))}


