function stageEffect(kind){const scene=$('adventureStage');if(!scene)return;const img=document.createElement('img');img.className='stage-effect effect-'+kind;img.alt='';img.setAttribute('aria-hidden','true');img.src='./art/effect-'+kind+'.svg';scene.appendChild(img);setTimeout(()=>img.remove(),950)}
function queueEncounter(name,won,result){stageQueue.push({name,won,result});if(stageQueue.length>12)stageQueue=stageQueue.slice(-12)}
function stageHit(){if(stageBusy||!stageEnabled||document.hidden)return;const hero=$('heroActor'),mob=$('mobActor'),scene=$('adventureStage');if(!hero||!mob||!scene)return;const encounter=stageQueue.shift();if(!encounter)return;stageBusy=true;stageBeat++;$('stageEnemy').textContent=encounter.name;mob.dataset.kind=monsterLook(encounter.name).tone;mob.innerHTML=monsterSprite(encounter.name);mob.classList.toggle('boss-actor',/主管|首領|暴君/.test(encounter.name));const result=encounter.result;const events=(result&&result.events||[]).filter(e=>e.damage||e.type==='heal'||e.type==='miss').slice(0,20);const total=events.length;let step=0;const enemyMax=Math.max(1,result?.maxHp||1),heroMax=Math.max(1,result?.maxHeroHp||1);const damageLabel=document.createElement('div');damageLabel.className='damage-float v10-fight-number';scene.appendChild(damageLabel);const finish=()=>{damageLabel.remove();hero.classList.remove('attacking','hurt');mob.classList.remove('hurt','defeated');stageWave++;$('stageWave').textContent='第 '+(stageWave+1)+' 次遭遇';stageToast(encounter.won?'討伐成功 · 獎勵已結算':'戰鬥結束 · 繼續探索');$('stageEnemyHp').style.width='100%';$('stageEnemy').textContent='巡邏中 · 等待遭遇';stageBusy=false};const advance=()=>{if(!stageEnabled||document.hidden){finish();return}hero.classList.remove('attacking','hurt');mob.classList.remove('hurt');if(step>=total){if(encounter.won)mob.classList.add('defeated');setTimeout(finish,360);return}const e=events[step++];const isHero=e.who==='hero',healing=e.type==='heal',miss=e.type==='miss';if(isHero&&!healing){hero.classList.add('attacking');mob.classList.add('hurt');if(e.hp!==undefined)$('stageEnemyHp').style.width=Math.max(0,Math.min(100,e.hp/enemyMax*100))+'%';stageEffect(e.type==='ultimate'?'coffee':'slash')}else if(!miss&&!healing){hero.classList.add('hurt')}damageLabel.textContent=healing?'+'+(e.value||0):miss?'MISS':'−'+(e.damage||0);damageLabel.className='damage-float v10-fight-number '+(healing?'v10-heal':isHero?'v10-hero-hit':'v10-enemy-hit');damageLabel.style.animation='none';void damageLabel.offsetWidth;damageLabel.style.animation='v10NumberPop .5s ease-out both';if(e.skill)$('stageStatus').textContent=e.skill;setTimeout(advance,460)};$('stageEnemyHp').style.width='100%';advance()}

function stageInit(){if(!$('adventureStage'))return;$('stageEnemyHp').style.width='100%';$('stageToggle').addEventListener('click',()=>{stageEnabled=!stageEnabled;$('stageToggle').textContent=stageEnabled?'暫停演出':'繼續演出';$('stageStatus').textContent=stageEnabled?'冒險演出中':'演出暫停';if(stageEnabled)stageHit()});stageTimer=setInterval(stageHit,2300);stageHit()}

function itemCard(it,action){const shape=gearShape(it),artifact=!!artifactLore(it),set=setForItem(it);const diff=powerOf(it)-powerOf(s.equipped[it.slot]);const button=action==='equip'?'<button class="btn" data-equip="'+it.id+'">穿戴</button>':action==='upgrade'?'<button class="btn" data-upgrade="'+it.slot+'">強化</button>':'<span class="tag">穿戴中</span>';return '<div class="item gear-item gear-r'+it.r+(action==='equip'&&diff>0?' gear-upgrade':'')+(artifact?' gear-artifact':'')+'"><div class="gear-icon r'+it.r+'" aria-hidden="true">'+gearItemArt(it)+'</div><div class="row"><div><b class="'+RAR[it.r]+'">'+escapeHtml(it.name)+'</b><p>'+RAR[it.r]+' · '+it.slot+' · '+({staff:'法杖',hammer:'戰錘',spear:'長槍',dagger:'匕首',katana:'斬刀',sword:'長劍',coat:'輕甲',plate:'重甲',armor:'護甲'}[shape]||'裝備')+' · Lv.'+it.level+(it.upgrade?' · +'+it.upgrade:'')+'</p><p>攻 '+it.atk+'　防 '+it.def+'　生命 '+it.hp+'　'+it.affix+' +'+it.bonus+'%'+(action==='equip'?' · 戰力差 '+(diff>=0?'+':'')+Math.floor(diff):'')+'</p>'+(artifact?'<p class="gear-artifact-tag">✦ 社畜傳說神器 ✦</p>':'')+(set?'<p class="gear-artifact-tag">'+set.icon+' 套裝：'+escapeHtml(set.name)+'</p>':'')+'<p class="gear-flavor">「'+escapeHtml(gearJoke(it))+'」</p></div>'+button+'</div></div>'}

