function localDateKey(){const t=parts(Date.now());return [t.y,String(t.m).padStart(2,'0'),String(t.d).padStart(2,'0')].join('-')}
function eventIndex(key){let h=2166136261;for(const c of key){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return (h>>>0)%EVENT_POOL.length}
function eventState(){const key=localDateKey(),ev=EVENT_POOL[eventIndex(key)];return {key,ev,done:s.dailyEvent&&s.dailyEvent.key===key}}
function eventChoose(i){const state=eventState();if(state.done)return;const c=state.ev.choices[i];if(!c)return;if(c[2]==='xp')xp(c[3]);if(c[2]==='gold')s.coins+=c[3];if(c[2]==='material')s.materials+=c[3];if(c[2]==='loot')loot(s.level,Math.max(1,rarity()));s.dailyEvent={key:state.key,choice:i};message(state.ev.title+'：'+c[1]);save();render()}
function weaponStyle(){const it=s.equipped['武器'];if(!it)return {id:'blade',name:'新手斬擊',bonus:1};const name=it.name||'';if(/法杖|魔杖|權杖|魔導|法典|書/.test(name))return {id:'staff',name:'加班魔法彈',bonus:1.08};if(/錘|鎚|槌|戰斧|斧|鐵拳/.test(name))return {id:'hammer',name:'下班重擊',bonus:1.16};if(/弓|弩|槍|標槍/.test(name))return {id:'ranged',name:'遠距速射',bonus:1.06};return {id:'blade',name:'薪水連斬',bonus:1.04}}
const SET_SKILLS={clockout:{name:'夕陽準時斬',kind:'sunset'},stealth:{name:'摸魚影分身',kind:'shadow'},overtime:{name:'週報禁術',kind:'arcane'},bonus:{name:'年終金幣暴擊',kind:'gold'},monday:{name:'週一不死咖啡',kind:'coffee'},meeting:{name:'會議終止令',kind:'verdict'},coffee:{name:'雷霆咖啡連擊',kind:'lightning'}};
function resolveFight(config){const costume=activeSetCostume(),setSkill=costume&&SET_SKILLS[costume.id],weapon=weaponStyle(),p=stats(),enemyName=config.name,maxHp=config.hp,enemyAtk=config.atk,enemyDef=config.def,skill=config.skill||'normal',boss=!!config.boss;let enemyHp=maxHp,heroHp=Math.max(1,Math.min(p.hp,config.startHp??p.hp)),round=0,history=[],events=[],guard=skill==='guard',burst=skill==='burst',lifesteal=Object.values(s.equipped).reduce((v,it)=>v+(it&&it.affix==='吸血'?it.bonus:0),0),heals=0;while(enemyHp>0&&heroHp>0&&round<35){round++;const ultimate=round%4===0,critical=Math.random()<Math.min(.65,p.crit),enemyArmor=/魔像|騎士|骷髏/.test(enemyName)?1.3:1,hit=Math.max(1,Math.round(p.atk*weapon.bonus*(ultimate?2.5:1)*(critical?1.8:1)-enemyDef*.55*enemyArmor));const shield=boss&&round%5===0?Math.max(1,Math.round(enemyDef*1.4)):0;const actualHit=Math.max(1,hit-shield);enemyHp=Math.max(0,enemyHp-actualHit);history.push('第'+round+'回合：勇者造成 '+actualHit+(critical?' 暴擊':'')+(shield?'，主管防禦減免 '+shield:'')+' 傷害。');events.push({who:'hero',type:ultimate?'ultimate':critical?'critical':weapon.id,damage:actualHit,hp:enemyHp,skill:ultimate?'下班奧義 · '+weapon.name:critical?weapon.name+' · 會心一擊':weapon.name});if(lifesteal>0){const recovered=Math.min(p.hp-heroHp,Math.max(1,Math.floor(actualHit*Math.min(.35,lifesteal/100))));heroHp+=recovered;if(recovered){heals+=recovered;events.push({who:'hero',type:'heal',value:recovered,hp:heroHp})}}if(enemyHp<=0)break;
 if(setSkill&&round%3===0){
  if(costume.id==='monday'){const restored=Math.min(p.hp-heroHp,Math.max(1,Math.round(p.hp*.11)));if(restored>0){heroHp+=restored;heals+=restored;events.push({who:'hero',type:'heal',value:restored,hp:heroHp,skill:setSkill.name});history.push(setSkill.name+'，恢復 '+restored+' HP。')}}
  else{const rate={clockout:.42,stealth:.32,overtime:.48,bonus:.45,meeting:.38,coffee:.28}[costume.id]||.3;const times=costume.id==='coffee'?2:1;for(let j=0;j<times&&enemyHp>0;j++){const damage=Math.max(1,Math.round(p.atk*rate));enemyHp=Math.max(0,enemyHp-damage);events.push({who:'hero',type:'set-'+setSkill.kind,damage,hp:enemyHp,skill:setSkill.name+(times>1?' '+(j+1)+'連擊':'')});history.push(setSkill.name+'，追加 '+damage+' 傷害。')}}
 }
 if(enemyHp<=0)break;if(costume&&costume.id==='stealth'&&round%3===0){events.push({who:'enemy',type:'miss',skill:'影分身閃避'});history.push('摸魚影分身閃避了反擊。');continue}
 if(Math.random()<Math.min(.5,p.dodge)){history.push('勇者閃避了敵人的攻擊。');events.push({who:'enemy',type:'miss'});continue}const special=round%4===0,bossSpecial=boss&&round%3===0,enemyStyle=/史萊姆|增殖|蜂群/.test(enemyName)?'swarm':/魔像|騎士|骷髏/.test(enemyName)?'tank':/忍者|蝙蝠|企鵝/.test(enemyName)?'swift':/惡魔|怨靈|幽靈|魔法師/.test(enemyName)?'magic':'office';const bossRage=boss&&maxHp>0&&enemyHp/maxHp<.35;let incoming=Math.max(1,Math.round(enemyAtk*(special?1.5:1)*(bossSpecial?1.35:1)*(bossRage?1.3:1)*(enemyStyle==='magic'?1.18:enemyStyle==='tank'?.88:1)*(guard?.48:1)-p.def*.3));heroHp=Math.max(0,heroHp-incoming);const trick=bossSpecial?'主管召開臨時會議':special?({swarm:'待辦事項大量增殖',tank:'防禦反擊',swift:'摸魚瞬步',magic:'精神耗竭咒',office:'急件轟炸'}[enemyStyle]):'普通攻擊';history.push(enemyName+' 使用'+trick+'，造成 '+incoming+' 傷害。');events.push({who:'enemy',type:bossSpecial?'boss':special?'special':'strike',damage:incoming,hp:heroHp,skill:bossRage?'暴走加班 · '+trick:trick});if(heroHp>0&&heroHp<p.hp*.72&&round%5===0){const recovered=Math.min(p.hp-heroHp,Math.round(p.hp*.3));heroHp+=recovered;heals+=recovered;history.push('勇者喝下公會急救咖啡，恢復 '+recovered+' HP。');events.push({who:'hero',type:'heal',value:recovered,hp:heroHp})}}return {win:enemyHp<=0,enemyName,enemyHp,maxHp,heroHp,maxHeroHp:p.hp,startHp:Math.max(1,Math.min(p.hp,config.startHp??p.hp)),round,heals,events,history:history.slice(-5)}}
function combat(f,wave=1,total=3,startHp){const boss=f%10===0&&wave===total,name=boss?'開會不結束的主管':ENEMIES[(f*3+wave*7)%ENEMIES.length],difficulty=f+Math.floor(wave/2);return resolveFight({name,hp:Math.round(23+difficulty*7+difficulty*difficulty*.12)*(boss?2:1),atk:Math.round(3+difficulty*1.25)*(boss?1.25:1),def:Math.round(1+difficulty*.55),boss,startHp})}

function wildEncounter(){const level=Math.max(1,Math.floor(s.minutes/90)+1),name=pick(ENEMIES);return resolveFight({name,hp:Math.round(32+level*13),atk:Math.round(4+level*2.2),def:Math.round(1+level*.8)})}

