function battleParticles(scene,ev){if(!scene||document.hidden)return;const kind=ev.type==='ultimate'?'ultimate':ev.type==='heal'?'heal':ev.type==='critical'?'critical':ev.type==='boss'?'boss':ev.type==='miss'?'miss':'hit';const fx=document.createElement('div');fx.className='battle-fx fx-'+kind;fx.classList.add(ev.who==='hero'&&ev.type!=='heal'?'target-enemy':'target-hero');fx.setAttribute('aria-hidden','true');fx.innerHTML='<span class="impact-core"></span><span class="impact-ring"></span>';const reduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;const count=reduced?0:kind==='ultimate'?14:kind==='critical'?9:kind==='heal'?8:5;for(let i=0;i<count;i++){const p=document.createElement('i');p.className='impact-spark';const angle=Math.PI*2*i/count,dist=(kind==='ultimate'?92:kind==='heal'?63:54)*(0.75+Math.random()*.5);p.style.setProperty('--dx',Math.round(Math.cos(angle)*dist)+'px');p.style.setProperty('--dy',Math.round(Math.sin(angle)*dist)+'px');p.style.setProperty('--delay',(i%3*25)+'ms');fx.appendChild(p)}scene.appendChild(fx);setTimeout(()=>fx.remove(),reduced?200:750);if(ev.damage||ev.value){const n=document.createElement('div');n.className='battle-number '+(ev.who==='hero'&&ev.type!=='heal'?'target-enemy':'target-hero')+' '+(ev.value?'number-heal':ev.type==='critical'?'number-critical':ev.type==='ultimate'?'number-ultimate':'');n.textContent=(ev.value?'+':'−')+(ev.value||ev.damage);scene.appendChild(n);setTimeout(()=>n.remove(),900)}}
let battleAudioEnabled=false,battleAudioContext=null;
function battleSound(type){if(!battleAudioEnabled)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;if(!battleAudioContext)battleAudioContext=new AC();if(battleAudioContext.state==='suspended')battleAudioContext.resume();const ctx=battleAudioContext,now=ctx.currentTime,osc=ctx.createOscillator(),gain=ctx.createGain(),preset={slash:[270,130,.095,'sawtooth'],critical:[550,210,.17,'triangle'],ultimate:[720,95,.32,'sawtooth'],heal:[480,800,.22,'sine'],boss:[130,60,.26,'sawtooth'],special:[300,110,.18,'square'],miss:[640,320,.1,'sine'],strike:[150,90,.11,'triangle']}[type]||[250,130,.12,'triangle'];osc.type=preset[3];osc.frequency.setValueAtTime(preset[0],now);osc.frequency.exponentialRampToValueAtTime(preset[1],now+preset[2]);gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.055,now+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+preset[2]);osc.connect(gain);gain.connect(ctx.destination);osc.start(now);osc.stop(now+preset[2]+.01)}catch(e){console.warn('Sound unavailable',e)}}
function toggleBattleSound(){battleAudioEnabled=!battleAudioEnabled;const b=$('battleSound');if(b)b.textContent=battleAudioEnabled?'🔊 音效開啟':'🔇 音效關閉';if(battleAudioEnabled)battleSound('heal')}
let replayTimer=null,replayQueue=[],replayActive=false,replaySpeed=1,replayTick=null,replayPause=null,replayCurrent=null,replayPaused=false,replayAtEnd=false,replayFrameBase=480;
function replayTower(result){replayQueue.push(result);if(!replayActive)playNextReplay()}
function replayFrameMs(){return Math.max(55,Math.round(replayFrameBase/replaySpeed))}
function replayFrameBudget(count){return Math.max(150,Math.min(480,Math.floor(14000/Math.max(1,count))))}
function playNextReplay(){if(replayPaused)return;replayAtEnd=false;const result=replayQueue.shift();if(!result){replayActive=false;replayCurrent=null;replayTick=null;replayAtEnd=false;replayPaused=false;updateReplayPauseButton();return}replayCurrent=result;replayActive=true;const scene=$('towerArena');if(!scene){replayActive=false;replayQueue.length=0;return}if(replayTimer)clearInterval(replayTimer);if(replayPause){clearTimeout(replayPause);replayPause=null}const hero=$('towerHero'),mob=$('towerMob'),caption=$('towerAction');let i=0;scene.classList.remove('victory','loss','impact-shake','ultimate-flash');scene.classList.toggle('boss-encounter',/主管|首領|暴君/.test(result.enemyName));const skillBar=$('towerSkillMeter');if(skillBar)skillBar.style.width='0%';hero.className='tower-sprite tower-hero';mob.className='tower-sprite tower-mob';$('towerArenaName').textContent='第 '+result.floor+' 層 · '+result.wave+'/'+result.totalWaves+' 波 · '+result.enemyName;mob.innerHTML=monsterSprite(result.enemyName)+'<div class="tower-health"><div id="towerEnemyLive"></div></div>';scene.dataset.enemy=monsterLook(result.enemyName).tone;const track=$('towerWaveTrack');if(track)track.innerHTML=Array.from({length:result.totalWaves},(_,k)=>'<span class="wave-pip '+(k+1<result.wave?'done':k+1===result.wave?'current':'')+'">'+(k+1)+'</span>').join('');const events=result.events||[];replayFrameBase=replayFrameBudget(events.length);const progress=$('battleProgress');if(progress)progress.textContent='第 '+result.floor+' 層 · 第 '+result.wave+'/'+result.totalWaves+' 波 · '+events.length+' 個戰鬥動作';const tick=()=>{if(replayPaused||document.hidden)return;if(i>=events.length){clearInterval(replayTimer);replayTimer=null;replayTick=null;replayAtEnd=true;scene.classList.remove('impact-shake','ultimate-flash');scene.classList.add(result.win?'victory':'loss');caption.textContent=result.win?(result.wave===result.totalWaves?'🏆 本層通關！下一層 HP 全滿':'✨ 第 '+result.wave+' 波擊退！繼續前進'):'💀 挑戰失敗，先喝杯咖啡再來';if(!document.hidden&&!replayPaused)replayPause=setTimeout(()=>{replayPause=null;playNextReplay()},Math.round(700/replaySpeed));return}const ev=events[i++];if(progress)progress.textContent='第 '+result.floor+' 層 · '+result.wave+'/'+result.totalWaves+' 波 · 動作 '+i+'/'+events.length;battleParticles(scene,ev);battleSound(ev.type);scene.classList.remove('impact-shake','ultimate-flash');scene.style.setProperty('--replay-duration',Math.max(90,Math.round(replayFrameMs()*.85))+'ms');void scene.offsetWidth;if(ev.type==='ultimate')scene.classList.add('ultimate-flash');else if(ev.type==='critical'||ev.type==='boss')scene.classList.add('impact-shake');hero.classList.remove('swing','heal','damaged','ultimate');mob.classList.remove('damaged','cast','special');void hero.offsetWidth;if(ev.who==='hero'){hero.classList.add(ev.type==='heal'?'heal':ev.type==='ultimate'?'ultimate':'swing');if(ev.type!=='heal')mob.classList.add('damaged')}else{mob.classList.add(ev.type==='boss'||ev.type==='special'?'special':'cast');if(ev.type!=='miss')hero.classList.add('damaged')}const skillBar=$('towerSkillMeter');if(skillBar&&ev.who==='hero'&&ev.type!=='heal'){const attacks=events.slice(0,i).filter(e=>e.who==='hero'&&e.damage).length,next=ev.type==='ultimate'?0:(attacks%4)/4;skillBar.style.width=Math.min(100,Math.max(0,next*100))+'%'}caption.textContent=ev.type==='ultimate'?'🌟 下班奧義！全自動大招 -'+ev.damage:ev.type==='heal'?'☕ 自動急救 +'+ev.value:ev.type==='miss'?'💨 摸魚閃避成功！':ev.type==='boss'?'📢 '+(ev.skill||'主管召開臨時會議')+' −'+ev.damage:ev.type==='special'?'⚡ '+(ev.skill||'急件突襲！'):(ev.who==='hero'?'⚔️ 勇者攻擊 -':'💥 怪物反擊 -')+ev.damage;if(ev.who==='hero'&&ev.type!=='heal')$('towerEnemyLive').style.width=Math.max(0,100*ev.hp/result.maxHp)+'%';if((ev.who==='enemy'&&ev.type!=='miss')||ev.type==='heal')$('towerHeroLive').style.width=Math.max(0,100*ev.hp/result.maxHeroHp)+'%'};$('towerEnemyLive').style.width='100%';$('towerHeroLive').style.width=(100*result.startHp/result.maxHeroHp)+'%';replayTick=tick;if(!document.hidden){tick();if(replayTick)replayTimer=setInterval(tick,replayFrameMs())}}
function setReplaySpeed(){replaySpeed=replaySpeed===1?2:replaySpeed===2?4:1;const b=$('battleSpeed');if(b)b.textContent='戰鬥速度 ×'+replaySpeed;if(replayActive&&!replayPaused&&!document.hidden&&replayTimer&&replayTick){clearInterval(replayTimer);replayTimer=setInterval(replayTick,replayFrameMs())}}
function updateReplayPauseButton(){const b=$('battlePause');if(b)b.textContent=replayPaused?'▶ 繼續演出':'⏸ 暫停演出'}
function toggleReplayPause(){if(!replayActive)return;replayPaused=!replayPaused;updateReplayPauseButton();if(replayPaused){clearInterval(replayTimer);replayTimer=null;clearTimeout(replayPause);replayPause=null}else if(replayTick&&!document.hidden){replayTimer=setInterval(replayTick,replayFrameMs())}else if(replayAtEnd&&!document.hidden){replayPause=setTimeout(()=>{replayPause=null;playNextReplay()},Math.round(500/replaySpeed))}}
function syncReplayVisibility(){if(document.hidden){clearInterval(replayTimer);replayTimer=null;if(replayPause){clearTimeout(replayPause);replayPause=null}}else if(replayActive&&!replayPaused){if(replayTick&&!replayTimer)replayTimer=setInterval(replayTick,replayFrameMs());else if(!replayTick&&!replayPause)replayPause=setTimeout(()=>{replayPause=null;playNextReplay()},Math.round(500/replaySpeed))}}
document.addEventListener('visibilitychange',syncReplayVisibility);
function skipBattleReplay(){if(!replayActive)return;clearInterval(replayTimer);clearTimeout(replayPause);replayTimer=null;replayPause=null;replayTick=null;replayAtEnd=false;const result=replayQueue.length?replayQueue[replayQueue.length-1]:replayCurrent;replayQueue.length=0;replayActive=false;replayPaused=false;updateReplayPauseButton();replayCurrent=null;const scene=$('towerArena');if(scene){scene.classList.remove('impact-shake','ultimate-flash');scene.classList.toggle('loss',!!result&&!result.win);scene.classList.toggle('victory',!!result&&result.win);$('towerAction').textContent='⏩ 已略過演出 · '+(result?(result.win?'本波勝利':'本波戰敗'):'戰鬥結束')+' · 獎勵結算不變';if(result){scene.classList.toggle('boss-encounter',/主管|首領|暴君/.test(result.enemyName));scene.dataset.enemy=monsterLook(result.enemyName).tone;$('towerArenaName').textContent='第 '+result.floor+' 層 · '+result.wave+'/'+result.totalWaves+' 波 · '+result.enemyName;const mob=$('towerMob');mob.className='tower-sprite tower-mob';mob.innerHTML=monsterSprite(result.enemyName)+'<div class="tower-health"><div id="towerEnemyLive"></div></div>';const hero=$('towerHero');hero.className='tower-sprite tower-hero';const track=$('towerWaveTrack');if(track)track.innerHTML=Array.from({length:result.totalWaves},(_,k)=>'<span class="wave-pip '+(k+1<=result.wave?'done':'')+'">'+(k+1)+'</span>').join('');const progress=$('battleProgress');if(progress)progress.textContent='第 '+result.floor+' 層 · 第 '+result.wave+'/'+result.totalWaves+' 波 · 演出已略過';const meter=$('towerSkillMeter');if(meter)meter.style.width='0%';$('towerEnemyLive').style.width=Math.max(0,100*result.enemyHp/result.maxHp)+'%';$('towerHeroLive').style.width=Math.max(0,100*result.heroHp/result.maxHeroHp)+'%'}}message('已略過戰鬥演出，實際戰鬥結果及獎勵不變。')}
function towerCombat(n){if(replayActive||replayQueue.length){message('戰鬥演出尚未結束，請稍候。');return}let wins=0,failed=false;for(let i=0;i<n;i++){const floor=s.tower,waves=3+floor%2;let hp=stats().hp,cleared=true;for(let wave=1;wave<=waves;wave++){const result=combat(floor,wave,waves,hp);result.floor=floor;result.wave=wave;result.totalWaves=waves;result.floorStart=wave===1;lastCombat=result;replayTower(result);hp=result.heroHp;if(!result.win){message('第 '+floor+' 層 · 第 '+wave+' 波失敗！'+result.enemyName+' 還剩 '+result.enemyHp+' HP。');cleared=false;failed=true;break}}if(!cleared)break;s.tower++;s.kills+=waves;wins++;s.coins+=10+floor*3;xp(12+floor*2);if(floor%10===0||Math.random()<.4)loot(floor,floor%10===0?Math.max(2,rarity()):undefined)}if(wins)message('突破 '+wins+' 層！每層 '+(3+(s.tower-1)%2)+' 波，進入下一層自動回滿血。');if(failed&&!wins)log('換裝備後再挑戰，這層會重新開始。');save();render()}

function todayType(){const t=parts(Date.now()),w=weekday(t.y,t.m,t.d);return w===1?'monday':w===5?'friday':null}
function weekKey(type){const t=parts(Date.now()),offset=(weekday(t.y,t.m,t.d)+6)%7,mon=new Date(Date.UTC(t.y,t.m-1,t.d)-offset*86400000);return mon.toISOString().slice(0,10)+'-'+type}
const DUNGEONS=[{id:'monday',icon:'⏰',name:'地獄星期一',desc:'鬧鐘暴君率領待辦事項大軍，週一經驗加倍。',base:65,coins:140,experience:140,rarity:2,boss:'週一鬧鐘暴君',stories:['鬧鐘暴君：「再睡五分鐘？先交報表！」','38 件待辦事項一起撲了上來，你用咖啡成功擊退它們。']},{id:'printer',icon:'🖨️',name:'卡紙魔像工廠',desc:'修理失控印表機，特別容易找到鍛造零件。',base:40,coins:90,experience:80,materials:8,rarity:1,boss:'印表機怨靈',stories:['魔像吐出一張紙：「錯誤代碼：我也想下班。」','印表機終於吐紙，結果印出的是你的請假申請。']},{id:'lunch',icon:'🍱',name:'午休便當保衛戰',desc:'保護最後一塊炸雞，金幣獎勵較高。',base:50,coins:210,experience:75,rarity:1,boss:'午休破壞者',stories:['便當魔王：「最後一塊雞排是我的！」你英勇守住午餐。','敵人偷走你的湯匙，但你用筷子完成反殺。']},{id:'meeting',icon:'📋',name:'無限會議迷宮',desc:'每次通關都要擊敗會議分身，經驗較高。',base:85,coins:100,experience:220,rarity:2,boss:'開會不結束的主管',stories:['會議終於結束，主管：「最後再補充三點。」','你擊破了 PowerPoint 的第 999 張投影片。']},{id:'friday',icon:'🏃',name:'週五魔王逃班城',desc:'魔王只想提早下班，週五掉寶品質提升。',base:35,coins:180,experience:100,rarity:2,boss:'提早下班的魔王',stories:['魔王留下便條紙：「我先下班，有事星期一再說。」','魔王跪求你打敗他，這樣他就能申請公傷假。']}];
function dungeonBonus(d){const today=todayType();return today===d.id}
function dungeonNeed(d,count){return d.base+count*22}
function dungeonWaves(d,count){const level=Math.max(1,s.level),scale=1+count*.16;const names={monday:['待辦事項增殖體','週報蝙蝠','週一鬧鐘暴君'],printer:['卡紙魔像','印表機怨靈'],lunch:['午休破壞者','便當守門哥布林','午休破壞者'],meeting:['會議骷髏兵','人資魔法師','開會不結束的主管','開會不結束的主管'],friday:['催件哥布林','提早下班的魔王']};return names[d.id].map((name,i,arr)=>{const boss=i===arr.length-1,modifier=d.id==='meeting'&&boss?1.35:d.id==='printer'?.85:1;return {name,hp:Math.round((28+level*10+i*15)*scale*(boss?1.35:1)*modifier),atk:Math.round((4+level*1.5+i*1.6)*scale*modifier),def:Math.round((2+level*.55+i)*scale*(d.id==='printer'?1.5:1)),boss}})}
const DUNGEON_SCENES={monday:{label:'⏰ 鬧鐘堡壘',tone:'clock'},printer:{label:'🖨️ 卡紙工廠',tone:'factory'},lunch:{label:'🍱 便當食堂',tone:'canteen'},meeting:{label:'📋 無盡會議廳',tone:'boardroom'},friday:{label:'🏰 魔王下班城',tone:'castle'}};
