function dungeonReplayView(){stopReplayFrames();const el=document.getElementById('dungeonReplay');if(!el||!dungeonReplay)return;const r=dungeonReplay,index=r.index,entry=r.results[index],final=index>=r.results.length-1&&!dungeonRun,won=r.won;const heroPercent=Math.max(0,Math.min(100,Math.round(entry.heroHp/Math.max(1,entry.maxHeroHp)*100))),enemyPercent=Math.max(0,Math.min(100,Math.round(entry.enemyHp/Math.max(1,entry.maxHp)*100)));el.classList.remove('hidden');el.innerHTML=dungeonScene(r.id)+'<div class="dungeon-replay-head"><span>⚔️ '+escapeHtml(r.name)+'</span><button type="button" class="btn" data-replay-close aria-label="關閉副本戰報">✕</button></div><div class="dungeon-replay-progress" aria-label="副本進度">'+r.results.map((x,i)=>'<span class="'+(i===index?'current':x.win?'cleared':'failed')+'">'+(i===index?'◆':x.win?'✓':'✕')+'</span>').join('')+'</div><div class="dungeon-replay-arena dungeon-world-arena dungeon-animated '+(entry.enemyName===r.boss?'dungeon-world-boss':'')+'"><img class="dungeon-world-background" src="./art/dungeon-'+r.id+'.svg?v=7.7" alt="" aria-hidden="true"><div class="dungeon-world-atmosphere" aria-hidden="true"></div><div class="dungeon-world-ground" aria-hidden="true"></div><div class="dungeon-world-strike" aria-hidden="true"><i></i><i></i><i></i></div><div class="dungeon-world-impact" aria-hidden="true"></div><div class="dungeon-replay-hero">'+heroEquipmentArt()+'<small>薪水勇者</small></div><div class="dungeon-replay-vs" aria-hidden="true">⚔</div><div class="dungeon-replay-enemy">'+(entry.enemyName===r.boss?'<div class="dungeon-boss-art"><img src="./art/boss-'+r.id+'.svg?v=7.8" alt="'+escapeHtml(entry.enemyName)+'"><small>'+escapeHtml(entry.enemyName)+'</small></div>':monsterSprite(entry.enemyName))+'</div></div><div class="dungeon-replay-wave">'+(entry.enemyName===r.boss?'👑 首領戰':'⚔️ 小怪戰')+' · 第 '+(index+1)+' / '+r.total+' 波</div><div class="dungeon-replay-bars"><div><span>勇者 HP '+entry.heroHp+' / '+entry.maxHeroHp+'</span><div class="dungeon-bar"><i style="width:'+heroPercent+'%"></i></div></div><div><span>敵人 HP '+entry.enemyHp+' / '+entry.maxHp+'</span><div class="dungeon-bar enemy"><i style="width:'+enemyPercent+'%"></i></div></div></div><div class="dungeon-replay-log">'+entry.history.map(x=>'<p>'+escapeHtml(x)+'</p>').join('')+'</div>'+(final?'<div class="dungeon-replay-result '+(won?'victory':'defeat')+'">'+(won?'🎁 通關寶箱開啟！':'💀 挑戰失敗，整裝後再來！')+'<p>'+escapeHtml(r.reward)+'</p></div>':'')+'<button class="btn dungeon-replay-again" data-replay-animate aria-label="重播戰鬥動作">⚔ 重播戰鬥演出</button>'+ '<button class="btn primary full" data-replay-next>'+(final?'結束戰報':dungeonRun?'繼續探索 · 選擇下一步 →':'前往下一波 →')+'</button>';el.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});replayFrames()}
