function stopReplayFrames(){if(replayFrameTimer!==null)clearInterval(replayFrameTimer);replayFrameTimer=null;replayFrameIndex=0}
function replayFrames(){stopReplayFrames();const r=dungeonReplay;if(!r)return;const entry=r.results[r.index],events=entry&&entry.events;if(!events||!events.length)return;const arena=document.querySelector('#dungeonReplay .dungeon-world-arena'),bars=document.querySelectorAll('#dungeonReplay .dungeon-replay-bars .dungeon-bar i'),labels=document.querySelectorAll('#dungeonReplay .dungeon-replay-bars span'),caption=document.getElementById('replayEventCaption');if(!arena||bars.length<2)return;let hero=entry.startHp,enemy=entry.maxHp;const draw=()=>{bars[0].style.width=Math.max(0,hero/Math.max(1,entry.maxHeroHp)*100)+'%';bars[1].style.width=Math.max(0,enemy/Math.max(1,entry.maxHp)*100)+'%';if(labels[0])labels[0].textContent='勇者 HP '+hero+' / '+entry.maxHeroHp;if(labels[1])labels[1].textContent='敵人 HP '+enemy+' / '+entry.maxHp};draw();if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){hero=entry.heroHp;enemy=entry.enemyHp;draw();if(caption)caption.textContent='戰鬥結束';return}const advance=()=>{if(dungeonReplay!==r||r.results[r.index]!==entry){stopReplayFrames();return}const e=events[replayFrameIndex++];if(!e){hero=entry.heroHp;enemy=entry.enemyHp;draw();if(caption)caption.textContent=entry.win?'⚔ 擊敗敵人！':'⚠ 勇者倒下了';stopReplayFrames();return}if(e.who==='hero'&&e.type!=='heal'&&e.hp!==undefined)enemy=e.hp;if(e.who==='enemy'&&e.hp!==undefined)hero=e.hp;if(e.type==='heal'&&e.hp!==undefined)hero=e.hp;draw();arena.classList.remove('replay-hit-hero','replay-hit-enemy','replay-style-staff','replay-style-hammer','replay-style-ranged','replay-style-blade','replay-style-ultimate');void arena.offsetWidth;arena.classList.add(e.who==='enemy'?'replay-hit-hero':'replay-hit-enemy');if(e.who==='hero'&&e.type!=='heal')arena.classList.add('replay-style-'+(e.type==='ultimate'?'ultimate':['staff','hammer','ranged','blade'].includes(e.type)?e.type:'blade'));if(e.type&&e.type.startsWith('set-')){arena.classList.add('replay-set-skill','replay-set-'+e.type.slice(4));setTimeout(()=>arena.classList.remove('replay-set-skill','replay-set-'+e.type.slice(4)),380)}const value=e.type==='heal'?'+'+e.value:e.type==='miss'?'MISS':'-'+(e.damage||0);const float=document.createElement('span');float.className='replay-floating-number '+(e.type==='critical'||e.type==='ultimate'?'critical ': '')+(e.type==='heal'?'heal ':'')+(e.who==='enemy'?'on-hero':'on-enemy');float.textContent=value;arena.appendChild(float);setTimeout(()=>float.remove(),650);if(caption)caption.textContent=e.type==='heal'?(e.skill||'☕ 急救咖啡'):e.type==='miss'?'💨 完美閃避':(e.skill||'普通攻擊')+(e.type==='critical'?' ✦ 暴擊！':'')};advance();replayFrameTimer=setInterval(advance,420)}
