const DUNGEON_DECISIONS={monday:{title:'鬧鐘響了！',text:'週一暴君要求你立刻回覆 38 封信。',choices:[['先喝一杯救命咖啡','每波後恢復更多生命', 'heal'],['直接把待辦清空','敵人生命減少，但攻擊提高','rush'],['假裝電腦正在更新','敵人攻擊降低，獎勵金幣減少','guard']]},printer:{title:'印表機冒煙了',text:'機器顯示「錯誤 404：上班動力不存在」。',choices:[['拔掉插頭重開','敵人生命減少','rush'],['仔細拆機維修','敵人攻擊降低，額外獲得零件','materials'],['用力拍兩下','敵人攻擊提高，額外獲得金幣','greed']]},lunch:{title:'便當只剩最後一塊雞排',text:'午休破壞者已經拿起叉子。',choices:[['先吃一口補血','每波後恢復更多生命','heal'],['拿筷子決鬥','敵人生命減少，但攻擊提高','rush'],['用飲料引開牠','敵人攻擊降低，金幣減少','guard']]},meeting:{title:'主管說：「最後補充三點」',text:'會議室的門突然鎖上。',choices:[['裝忙抄筆記','敵人攻擊降低，經驗減少','guard'],['直接離席','敵人生命減少，但攻擊提高','rush'],['挑戰主管的簡報','難度提高，額外經驗','greed']]},friday:{title:'魔王寄來請假申請',text:'他說今天只想準時下班。',choices:[['批准請假','敵人生命減少，金幣減少','guard'],['要求加班','難度提高，獎勵金幣增加','greed'],['一起翹班','每波後恢復更多生命','heal']]}};
const DUNGEON_EVENT_VARIANTS={monday:[{title:'信箱爆炸警報',text:'未讀郵件突然變成 999+。',choices:[['先整理信件','減少敵人攻擊','guard'],['全選標記已讀','敵人血量減少，但反擊變強','rush'],['泡第二杯咖啡','恢復生命','heal']]},{title:'主管臨時加派任務',text:'你已經快到終點，主管卻送來新工作。',choices:[['要求加班費','提高風險，增加獎勵','greed'],['先補充體力','恢復生命','heal'],['委婉拒絕','減少敵人攻擊','guard']]}],printer:[{title:'碳粉暴走',text:'整個工廠飄起黑色碳粉。',choices:[['戴上防護面罩','降低敵人攻擊','guard'],['用力搖晃機器','敵人生命降低，攻擊提高','rush'],['拆解零件','降低攻擊，額外零件','materials']]},{title:'維修員的秘密倉庫',text:'架上放著一盒可疑的全新零件。',choices:[['仔細回收','取得額外零件','materials'],['直接開機','敵人血量降低','rush'],['冒險超頻','提高難度，額外獎勵','greed']]}],lunch:[{title:'雞排保衛戰',text:'敵人正把最後一塊雞排夾走。',choices:[['先吃飽再打','恢復生命','heal'],['衝上去搶回來','敵人生命降低，但攻擊提高','rush'],['拿珍奶交換','降低敵人攻擊','guard']]},{title:'冰箱裡的神秘便當',text:'便當上寫著「請勿偷吃」，但散發神奇香氣。',choices:[['聞香補充精神','恢復生命','heal'],['小心保存','降低敵人攻擊','guard'],['拿去拍賣','提高難度，額外獎勵','greed']]}],meeting:[{title:'投影片第 999 頁',text:'主管還沒有講到重點。',choices:[['趁機喝咖啡','恢復生命','heal'],['直接跳到結論','敵人生命降低，攻擊提高','rush'],['挑戰所有數據','高風險額外獎勵','greed']]},{title:'臨時被點名報告',text:'全場突然安靜，所有人都看著你。',choices:[['裝忙翻筆記','降低敵人攻擊','guard'],['直接說重點','敵人生命降低','rush'],['提出加薪要求','高風險額外獎勵','greed']]}],friday:[{title:'魔王的下班倒數',text:'距離下班只剩五分鐘。',choices:[['一起打卡離開','恢復生命','heal'],['要求完成交接','降低敵人攻擊','guard'],['攔下魔王談加薪','高風險額外獎勵','greed']]},{title:'最後一封緊急郵件',text:'信件標題是「不急，但今天要」。',choices:[['明天再處理','降低敵人攻擊','guard'],['立刻處理','敵人生命降低，攻擊提高','rush'],['要求急件獎金','高風險額外獎勵','greed']]}]};
function dungeonEvent(id,wave){if(wave===0)return DUNGEON_DECISIONS[id];const variants=DUNGEON_EVENT_VARIANTS[id];return variants[(wave-1)%variants.length]}
