let autoPilot=false,autoRuns=0,autoWins=0,autoDrops=0,autoTickBusy=false,autoLosses=0,autoCoins=0,autoItems=0,autoMaterials=0,autoLevels=0,autoStreak=0,autoLastEvent='等待勇者出發',autoSnapshot=null,autoLastResult=null;
function autoPick(event,hpRatio){const scores=event.choices.map(c=>{const effect=c[2];return effect==='heal'?(hpRatio<.75?9:3):effect==='guard'?7:effect==='materials'?6:effect==='rush'?(hpRatio>.8?6:2):effect==='greed'?(hpRatio>.9?3:0):1});return scores.indexOf(Math.max(...scores))}
function autoChooseDungeon(){const p=stats().power;return DUNGEONS.filter(d=>p>=dungeonNeed(d,s.weekly[weekKey('dungeon-'+d.id)]||0)).sort((a,b)=>{const score=d=>{const n=dungeonNeed(d,s.weekly[weekKey('dungeon-'+d.id)]||0);return (d.coins+d.experience*.8+(d.materials||0)*12)/Math.max(25,n)*Math.min(1.4,p/Math.max(1,n))};return score(b)-score(a)})[0]}
function autoOpenChests(){let count=0;while(count<30&&Math.floor(s.minutes/90)>s.opened){s.opened++;s.coins+=60+s.level*5;loot(s.level,Math.max(1,rarity()));count++}return count}
function autoEquipBest(){let count=0;for(const x of bestEquipmentPlan()){const i=s.inventory.findIndex(it=>it.id===x.it.id);if(i<0)continue;s.inventory.splice(i,1);if(x.old)s.inventory.push(x.old);s.equipped[x.slot]=x.it;count++}return count}
function autoPilotUI(){const el=document.getElementById('autoPilotStatus');if(el)el.textContent=autoPilot?'運作中 · 已探索 '+autoRuns+' 次 · 通關 '+autoWins+' 次 · 開箱 '+autoDrops+' 個':'已停止 · 智慧策略／平衡風險';const statsEl=document.getElementById('autoPilotStats');if(statsEl)statsEl.innerHTML='<div><strong>'+num(autoRuns)+'</strong><small>冒險次數</small></div><div><strong>'+num(autoWins)+'</strong><small>通關</small></div><div><strong>'+num(autoLosses)+'</strong><small>失敗</small></div><div><strong>'+num(autoCoins)+'</strong><small>獲得金幣</small></div><div><strong>'+num(autoItems)+'</strong><small>取得裝備</small></div><div><strong>'+num(autoDrops)+'</strong><small>開啟寶箱</small></div>';const msg=document.getElementById('autoPilotEvent');if(msg)msg.textContent=autoLastEvent;const b=document.getElementById('autoPilotToggle');if(b)b.textContent=autoPilot?'■ 停止自動託管':'▶ 開始自動託管'}
function autoPilotStop(note){autoPilot=false;autoReplayHold=0;autoPilotUI();if(note){autoLastEvent=note;message(note)}}
function autoPilotStep(){if(!autoPilot||autoTickBusy||document.hidden)return;autoTickBusy=true;try{if(dungeonReplay&&dungeonRun){if(replayFrameTimer!==null)return;if(autoReplayHold<1){autoReplayHold++;autoLastEvent='🎬 觀看第 '+dungeonReplay.results.length+' 波戰鬥演出';dungeonReplayAnimate();return}autoReplayHold=0;dungeonReplay=null}if(dungeonRun){const run=dungeonRun;if(run.results.length<run.waves.length){const event=dungeonEvent(run.id,run.results.length),choice=autoPick(event,run.hp/Math.max(1,stats().hp));run.effects.push(event.choices[choice][2]);autoLastEvent='第 '+(run.results.length+1)+' 波：'+event.choices[choice][0];dungeonNextWave()}return}if(dungeonReplay){if(replayFrameTimer!==null)return;if(autoReplayHold<2){autoReplayHold++;autoLastEvent='🎬 '+dungeonReplay.name+' · '+(dungeonReplay.won?'通關演出':'戰鬥回放');if(autoReplayHold===1)dungeonReplayAnimate();return}autoReplayHold=0;const r=dungeonReplay;if(r.won&&r.results.length&&r.results[r.results.length-1].win){autoWins++;autoStreak++;autoLastEvent='🏆 通關 '+r.name+' · 連勝 '+autoStreak+' 次'}else{autoLosses++;autoStreak=0;autoLastEvent='⚠ '+r.name+' 挑戰失敗，重新評估副本'}if(autoSnapshot){autoCoins+=Math.max(0,Math.floor(s.coins-autoSnapshot.coins));autoItems+=Math.max(0,s.serial-autoSnapshot.serial);autoMaterials+=Math.max(0,s.materials-autoSnapshot.materials);autoLevels+=Math.max(0,s.level-autoSnapshot.level);autoSnapshot=null}dungeonReplay=null;const el=document.getElementById('dungeonReplay');if(el){el.classList.add('hidden');el.innerHTML=''}}const chests=autoOpenChests();autoDrops+=chests;const equipped=autoEquipBest();if(chests||equipped)autoLastEvent='🎁 開箱 '+chests+' 個 · 換裝 '+equipped+' 件';const d=autoChooseDungeon();if(!d){autoPilotStop('目前戰力不足以挑戰副本，請先升級裝備。');save();render();return}const event=dungeonEvent(d.id,0);autoRuns++;autoSnapshot={coins:s.coins,serial:s.serial,materials:s.materials,level:s.level};autoLastEvent='⚔ 出發：'+d.name+' · '+event.title;autoReplayHold=0;dungeon(d.id,autoPick(event,1));save();render()}catch(err){console.error('Autopilot stopped:',err);autoPilotStop('自動託管遇到錯誤，已安全停止。')}finally{autoTickBusy=false;autoPilotUI()}}
