function dungeonDecision(id){if(dungeonRun)return;const d=DUNGEONS.find(x=>x.id===id);if(!d)return;const count=s.weekly[weekKey('dungeon-'+id)]||0,need=dungeonNeed(d,count);if(stats().power<need){message('「'+d.name+'」需要 '+need+' 戰力，目前還不夠。');return}pendingDungeon=id;const event=dungeonEvent(id,0),el=document.getElementById('dungeonReplay');if(!el)return;el.classList.remove('hidden');el.innerHTML=dungeonScene(id)+'<div class="dungeon-decision"><div class="dungeon-replay-head"><span>✦ '+escapeHtml(d.name)+' · 冒險抉擇</span><button class="btn" data-decision-cancel aria-label="取消副本">✕</button></div><h3>'+escapeHtml(event.title)+'</h3><p>'+escapeHtml(event.text)+'</p><div class="dungeon-decision-options">'+event.choices.map((c,i)=>'<button type="button" class="btn dungeon-decision-option" data-decision="'+i+'"><strong>'+escapeHtml(c[0])+'</strong><small>'+escapeHtml(c[1])+'</small></button>').join('')+'</div></div>';el.scrollIntoView({behavior:'smooth',block:'nearest'})}
let dungeonRun=null;
function dungeon(id,decisionIndex=0){const d=DUNGEONS.find(x=>x.id===id);if(!d)return;const count=s.weekly[weekKey('dungeon-'+id)]||0,need=dungeonNeed(d,count);if(stats().power<need){message('戰力不足，需要 '+need+'。');return}dungeonRun={id,count,waves:dungeonWaves(d,count),hp:stats().hp,results:[],effects:[DUNGEON_DECISIONS[id].choices[decisionIndex][2]],extraMaterials:0,extraCoins:0,extraXp:0};dungeonNextWave()}
function dungeonNextWave(){const run=dungeonRun;if(!run)return;const d=DUNGEONS.find(x=>x.id===run.id),i=run.results.length,enemy={...run.waves[i]},effect=run.effects[run.effects.length-1];if(effect==='rush'){enemy.hp=Math.max(1,Math.round(enemy.hp*.72));enemy.atk=Math.round(enemy.atk*1.2)}if(effect==='guard'||effect==='materials')enemy.atk=Math.max(1,Math.round(enemy.atk*.78));if(effect==='greed'){enemy.hp=Math.round(enemy.hp*1.25);enemy.atk=Math.round(enemy.atk*1.12)}if(run.id==='lunch'&&i===1)enemy.hp=Math.round(enemy.hp*.8);if(run.id==='printer'&&i===1)enemy.def=Math.round(enemy.def*1.35);if(run.id==='friday'&&i===run.waves.length-1&&Math.random()<.35){enemy.hp=Math.round(enemy.hp*.65);enemy.atk=Math.round(enemy.atk*.75)}const result=resolveFight({...enemy,startHp:run.hp});run.results.push(result);run.hp=result.heroHp;lastCombat=result;if(!result.win){message('【'+d.name+'】第 '+(i+1)+' 波失敗，整裝後可重試。');dungeonReplayStart(d,run.results,false,'挑戰失敗，沒有扣除每週通關次數。');dungeonRun=null;render();return}if(effect==='heal')run.hp=Math.min(stats().hp,run.hp+Math.round(stats().hp*.16));if(run.id==='monday')run.hp=Math.min(stats().hp,run.hp+Math.round(stats().hp*.15));if(run.id==='lunch')run.hp=Math.min(stats().hp,run.hp+Math.round(stats().hp*.22));if(run.id==='friday')run.hp=Math.min(stats().hp,run.hp+Math.round(stats().hp*.25));if(effect==='materials')run.extraMaterials+=Math.min(6,3+i);if(effect==='greed'){run.extraCoins+=Math.min(40,20+i*5);run.extraXp+=Math.min(40,20+i*5)}if(i===run.waves.length-1){const bonus=dungeonBonus(d),coins=Math.round(d.coins*(bonus?1.5:1))+run.extraCoins,experience=Math.round(d.experience*(bonus?2:1))+run.extraXp,materials=(d.materials||0)+(bonus&&d.materials?4:0)+run.extraMaterials;s.weekly[weekKey('dungeon-'+run.id)]=run.count+1;s.kills+=run.waves.length;s.coins+=coins;xp(experience);s.materials+=materials;const it=loot(Math.max(s.level,5+run.count*2),run.count===0?Math.min(5,d.rarity+(bonus?1:0)):undefined);if(run.id==='friday'&&bonus&&Math.random()<.18&&!s.relics.includes('魔王的請假單'))s.relics.push('魔王的請假單');const reward='金幣 +'+coins+' · 經驗 +'+experience+' · 零件 +'+materials+' · '+it.name;message('【'+d.name+'】通關！'+reward);save();dungeonReplayStart(d,run.results,true,reward);dungeonRun=null;render();return}dungeonReplayStart(d,run.results,false,'');dungeonReplay.index=i;dungeonReplayView()}
