function dungeonCards(power){return '<div class="dungeon-grid">'+DUNGEONS.map(d=>{const count=s.weekly[weekKey('dungeon-'+d.id)]||0,need=dungeonNeed(d,count),bonus=dungeonBonus(d),ready=power>=need;return '<article class="dungeon-card '+(bonus?'dungeon-featured':'')+'"><div class="dungeon-card-heading"><span class="dungeon-emoji">'+d.icon+'</span><div><h3>'+d.name+'</h3><small>首領：'+d.boss+'</small></div></div><p>'+d.desc+'</p><div class="dungeon-rewards">金幣 '+Math.round(d.coins*(bonus?1.5:1))+' · 經驗 '+Math.round(d.experience*(bonus?2:1))+(d.materials?' · 零件 '+(d.materials+(bonus?4:0)):'')+'</div><p class="dungeon-requirement">建議戰力 '+need+' · '+({monday:3,printer:2,lunch:3,meeting:4,friday:2}[d.id]||3)+' 波連戰 · 本週通關 '+count+' 次'+(bonus?' · 今日加成':'')+'</p><button class="btn '+(ready?'primary':'')+' full" data-dungeon="'+d.id+'" '+(ready?'':'disabled')+'>'+(ready?'挑戰副本':'戰力不足')+'</button></article>'}).join('')+'</div>'}
function oldTower(n){let wins=0,txt='';for(let i=0;i<n;i++){const f=s.tower,need=24+Math.floor(f*7.5+f*f*.1);if(stats().power<need){txt='守衛要求你先回去練等（建議戰力 '+need+'）。';break}s.tower++;s.kills++;wins++;s.coins+=10+f*3;xp(12+f*2);if(f%10===0||Math.random()<.4)loot(f,f%10===0?Math.max(2,rarity()):undefined);txt=f%10===0?'擊敗第 '+f+' 層首領「開會不結束的主管」！':'擊敗第 '+f+' 層守衛。'}message(wins?'連續通關 '+wins+' 層！'+txt:txt);save();render()}
