function renderWorldJourney(){const kills=Math.max(0,s.kills||0),region=[...WORLD_REGIONS].reverse().find(x=>kills>=x.min)||WORLD_REGIONS[0],index=WORLD_REGIONS.indexOf(region),pct=Math.max(0,Math.min(100,Math.round((kills-region.min)/(region.goal-region.min)*100)));const name=document.getElementById('worldRegionName'),journey=document.getElementById('worldJourney'),count=document.getElementById('worldKills'),progress=document.getElementById('worldProgressFill'),label=document.getElementById('worldProgressText'),scene=document.querySelector('.v10-world-scene');if(name)name.textContent=region.name;if(journey)journey.textContent='第 '+(index+1)+' 區 · '+(index===WORLD_REGIONS.length-1?'最終遠征':'探索中');if(count)count.textContent='累計討伐 '+kills;if(progress)progress.style.width=pct+'%';if(label)label.textContent=(kills-region.min)+' / '+(region.goal-region.min)+' · '+pct+'%';if(scene)scene.dataset.region=String(index)}
