$('salvage').addEventListener('click',()=>{const n=s.inventory.filter(it=>it.r===0).length;if(!n){message('沒有普通裝備可分解。');return}s.inventory=s.inventory.filter(it=>it.r!==0);s.materials+=n*2;message('分解 '+n+' 件普通裝備，獲得 '+n*2+' 個零件。');save();render()});
document.addEventListener('click',e=>{const toggle=e.target.closest('[data-autopilot-toggle]');if(toggle){autoPilot=!autoPilot;autoPilotUI();if(autoPilot){message('智慧託管啟動：自動探索、戰鬥、首領、開箱、換裝。');autoPilotStep()}else message('自動託管已停止。');return;}const collect=e.target.closest('[data-idle-collect]');if(collect){const overlay=document.getElementById('idleRewardOverlay');if(overlay)overlay.remove();return;}const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-replay-close')){stopReplayFrames();if(autoPilot)autoPilotStop('已手動關閉戰報，自動託管暫停。');dungeonRun=null;dungeonReplay=null;const el=document.getElementById('dungeonReplay');if(el){el.classList.add('hidden');el.innerHTML=''}return}if(b.hasAttribute('data-replay-animate')){dungeonReplayAnimate();return}if(b.hasAttribute('data-replay-next')){stopReplayFrames();if(dungeonRun&&dungeonRun.results.length<dungeonRun.waves.length){dungeonIntermission();return}if(!dungeonReplay)return;if(dungeonReplay.index<dungeonReplay.results.length-1){dungeonReplay.index++;dungeonReplayView()}else{dungeonReplay=null;const el=document.getElementById('dungeonReplay');if(el){el.classList.add('hidden');el.innerHTML=''}}return}if(b.hasAttribute('data-run-abandon')){if(autoPilot)autoPilotStop('已手動撤退，自動託管暫停。');dungeonRun=null;dungeonReplay=null;const el=document.getElementById('dungeonReplay');if(el){el.classList.add('hidden');el.innerHTML=''}message('已撤退，本次沒有領取通關獎勵。');return}if(b.hasAttribute('data-run-choice')){if(dungeonRun){dungeonRun.effects.push(dungeonEvent(dungeonRun.id,dungeonRun.results.length).choices[Number(b.dataset.runChoice)][2]);dungeonNextWave()}return}if(b.hasAttribute('data-decision-cancel')){pendingDungeon=null;const el=document.getElementById('dungeonReplay');if(el){el.classList.add('hidden');el.innerHTML=''}return}if(b.hasAttribute('data-decision')){const id=pendingDungeon;pendingDungeon=null;if(id)dungeon(id,Number(b.dataset.decision));return}if(b.dataset.dungeon){if(autoPilot)autoPilotStop('已切換手動副本，自動託管暫停。');if(dungeonRun){message('請先完成或撤退目前副本。');return}dungeonDecision(b.dataset.dungeon);return}if(b.dataset.choice!==undefined){eventChoose(+b.dataset.choice);return}if(b.dataset.equip){const i=s.inventory.findIndex(it=>it.id===+b.dataset.equip);if(i<0)return;const it=s.inventory.splice(i,1)[0],old=s.equipped[it.slot];if(old)s.inventory.push(old);s.equipped[it.slot]=it;message('已穿戴「'+it.name+'」。');save();render();equipmentFeedback('✦ 已裝備 '+it.name,it.r)}if(b.dataset.upgrade){const it=s.equipped[b.dataset.upgrade];if(!it)return;const cost=40*(1+it.upgrade)*(1+it.r),mat=1+it.upgrade;if(s.coins<cost||s.materials<mat){message('金幣或零件不足。');return}s.coins-=cost;s.materials-=mat;it.upgrade++;it.atk+=2+it.r;it.def+=1+it.r;it.hp+=6+it.r*3;message('強化成功！'+it.name+' +'+it.upgrade);save();render();equipmentFeedback('✦ 強化成功 '+it.name+' +'+it.upgrade,it.r)}});
$('exportSave').addEventListener('click',async()=>{const data=btoa(unescape(encodeURIComponent(JSON.stringify(s))));try{await navigator.clipboard.writeText(data);alert('存檔已複製。')}catch{prompt('請複製以下存檔：',data)}});
$('importSave').addEventListener('click',()=>{const data=prompt('貼上存檔：');if(!data)return;try{const v=JSON.parse(decodeURIComponent(escape(atob(data.trim()))));if(v.version!==51||!Array.isArray(v.inventory)||!v.equipped)throw Error();if(!confirm('確定覆蓋目前存檔？'))return;s=v;s.last=Date.now();save();render();alert('匯入成功。')}catch{alert('存檔格式錯誤。')}});
